import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.l66uSLlc.js";const u=JSON.parse('{"title":"Install and first open","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md","lastUpdated":1789542331000}'),i={name:"guide/install.md"};function s(l,e,r,d,p,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="install-and-first-open" tabindex="-1">Install and first open <a class="header-anchor" href="#install-and-first-open" aria-label="Permalink to &quot;Install and first open&quot;">​</a></h1><p>Download builds from the <a href="https://github.com/roobli/Noto/releases" target="_blank" rel="noreferrer">releases page</a>. Prefer the latest tagged release. The current useful line is <strong>0.0.2-alpha</strong>; alphas are labelled.</p><p>Until Noto is signed with an Apple Developer ID and notarized (and an equivalent Windows certificate), each OS will warn once the first time you open a download. That is expected. Follow the steps below so the first launch is smooth.</p><p>Latest build linked from this site: <a href="https://github.com/roobli/Noto/releases/tag/v0.0.2-alpha.30" target="_blank" rel="noreferrer">v0.0.2-alpha.30</a>.</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><ol><li><p>Download <code>Noto-&lt;version&gt;-macos-arm64.zip</code> (Apple silicon). Intel builds appear on the releases page when published for that tag.</p></li><li><p>Unzip. You should get <code>Noto.app</code> (move it to <code>/Applications</code> if you like).</p></li><li><p><strong>First open</strong> — pick one:</p><p><strong>Right-click → Open</strong> (or Control-click → Open), then confirm <strong>Open</strong>.</p><p>Or in Terminal, from the folder that contains <code>Noto.app</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Noto.app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Noto.app</span></span></code></pre></div></li></ol><h3 id="what-the-dialogs-mean" tabindex="-1">What the dialogs mean <a class="header-anchor" href="#what-the-dialogs-mean" aria-label="Permalink to &quot;What the dialogs mean&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dialog</th><th>What to do</th></tr></thead><tbody><tr><td><strong>&quot;Noto&quot; cannot be opened because Apple cannot check it for malicious software</strong> / <strong>unidentified developer</strong></td><td>Right-click → Open once, or run the <code>xattr</code> line above. After that, double-click works.</td></tr><tr><td><strong>&quot;Noto&quot; is damaged and can&#39;t be opened</strong></td><td>Re-download the zip from the current release (avoid an old cached copy). Then run <code>xattr -cr Noto.app</code> and try Right-click → Open.</td></tr></tbody></table><p>True notarization (no Gatekeeper prompt) needs an Apple Developer identity on the release machine. Until then, the warning on first open is normal.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li>Download <code>NotoSetup-&lt;version&gt;.exe</code> (or the zip archive when one is attached).</li><li>Run the installer. If SmartScreen says <strong>Windows protected your PC</strong>, click <strong>More info</strong>, then <strong>Run anyway</strong>.</li><li>Finish the installer and launch Noto from the Start menu.</li></ol><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><ul><li><strong>Debian / Ubuntu:</strong> <code>sudo apt install ./noto_&lt;version&gt;_amd64.deb</code> (exact filename varies by tag; check the release assets).</li><li><strong>Fedora / openSUSE:</strong> <code>sudo rpm -i noto-&lt;version&gt;-….rpm</code></li><li><strong>Archive:</strong> when a <code>.tar.gz</code> is attached, unpack it and run the <code>noto</code> binary inside.</li></ul><p>No code signing is required on typical Linux desktops for these packages.</p><h2 id="in-app-updates" tabindex="-1">In-app updates <a class="header-anchor" href="#in-app-updates" aria-label="Permalink to &quot;In-app updates&quot;">​</a></h2><p>Packaged builds can check GitHub Releases from <strong>Settings → Updates</strong>:</p><ul><li><strong>Stable</strong> (default) — formal releases only</li><li><strong>Testing</strong> — includes prerelease alphas</li></ul><p>Check-on-launch and auto-download are off by default.</p><h2 id="after-install" tabindex="-1">After install <a class="header-anchor" href="#after-install" aria-label="Permalink to &quot;After install&quot;">​</a></h2><p>See <a href="./using">Using Noto</a> for the day-to-day shortcuts and the vault rail.</p>',20)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
